from __future__ import annotations

import json
import shutil
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(ROOT / "src"))

from scanner.engine import ScannerEngine
from scanner.models import Problem

OUT = ROOT / "run-data" / "meta_strategy" / "strategy_validation_feedback"
MEMORY = OUT / "memory.json"
SCANS = OUT / "scans"
CONTROL = OUT / "control"

# Synthetic opaque outputs of an EXTERNAL validator.  These numbers are not
# physics and are not generated by Scanner.  Their sole purpose is to test
# whether blind/domain validation can train routing without touching the
# experiment or the physical operator.
VALIDATION_SCHEDULE = {
    "direct": [0.45, 0.50, 0.48],
    "analogy": [0.62, 0.59, 0.61],
    "hybrid": [0.83, 0.86, 0.84],
}


def problem(i: int) -> Problem:
    return Problem(
        title=f"validation-transfer problem {i}",
        description="same discovery family; strategy quality is supplied only after scan by a held-out validator",
        domain="method-test",
        tags=["blind-validation", "strategy-learning", f"instance-{i}"],
        payload={
            "table": {
                "a": [0, 1, 2, 3, 4, 5],
                "b": [0, 1.1, 1.9, 3.2, 3.8, 5.1],
                "c": [5, 4, 3, 2, 1, 0],
            }
        },
        constraints={"physical_operator_must_not_change": True},
    )


def main() -> None:
    if OUT.exists():
        shutil.rmtree(OUT)
    OUT.mkdir(parents=True)

    engine = ScannerEngine(MEMORY, SCANS)
    training = []
    k = 0
    for strategy in ("direct", "analogy", "hybrid"):
        for score in VALIDATION_SCHEDULE[strategy]:
            rec = engine.scan(problem(k), force_strategy=strategy)
            if rec.baseline.strategy != "direct":
                raise AssertionError("baseline changed from direct")
            engine.validate_scan(
                rec,
                score,
                details={"source": "synthetic-held-out-validator", "method_test_only": True},
            )
            training.append({
                "scan_id": rec.scan_id,
                "forced_strategy": strategy,
                "baseline_strategy": rec.baseline.strategy,
                "validation_score": score,
            })
            k += 1

    learned = engine.scan(problem(100))
    if learned.baseline.strategy != "direct":
        raise AssertionError("learned scan changed baseline")
    if learned.learner.strategy != "hybrid":
        raise AssertionError(f"expected hybrid from external validation, got {learned.learner.strategy}")

    # Negative control: no validation history -> no learned validation preference.
    control_engine = ScannerEngine(CONTROL / "memory.json", CONTROL / "scans")
    control = control_engine.scan(Problem(
        title="unseen neutral problem",
        description="no prior memory and no external validation",
        domain="fresh-control",
        tags=["fresh", "unseen"],
        payload={"table": {"x": [0, 1, 2, 3], "y": [0, 1, 4, 9]}},
    ))
    if control.learner.strategy != "direct":
        raise AssertionError(f"fresh control should use direct, got {control.learner.strategy}")

    stats = {s: engine.memory.strategy_stats(s) for s in ("direct", "analogy", "hybrid")}
    result = {
        "experiment": "strategy_validation_feedback",
        "status": "methodological control only; no physical result",
        "training": training,
        "strategy_stats_after_validation": stats,
        "learned_unforced_strategy": learned.learner.strategy,
        "fresh_no_validation_control_strategy": control.learner.strategy,
        "baseline_preserved_direct": True,
        "operator_modified_by_learner": False,
        "expected_mean_validation": {
            s: sum(v) / len(v) for s, v in VALIDATION_SCHEDULE.items()
        },
        "conclusion": "External validation feedback changes future routing while the direct baseline and physical experiment remain untouched.",
    }
    (OUT / "summary.json").write_text(json.dumps(result, indent=2), encoding="utf-8")
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()
